  1642  GF_Err hdlr_box_read(GF_Box *s, GF_BitStream *bs)
  1643  {
  1644          u64 cookie;
  1645          GF_HandlerBox *ptr = (GF_HandlerBox *)s;
  1646
  1647          ISOM_DECREASE_SIZE(ptr, 20);
  1648          ptr->reserved1 = gf_bs_read_u32(bs);
  1649          ptr->handlerType = gf_bs_read_u32(bs);
  1650          gf_bs_read_data(bs, (char*)ptr->reserved2, 12);
  1651
  1652          cookie = gf_bs_get_cookie(bs);
  1653          if (ptr->handlerType==GF_ISOM_MEDIA_VISUAL)
  1654                  cookie |= GF_ISOM_BS_COOKIE_VISUAL_TRACK;
  1655          else
  1656                  cookie &= ~GF_ISOM_BS_COOKIE_VISUAL_TRACK;
  1657          gf_bs_set_cookie(bs, cookie);
  1658
  1659          if (ptr->size) {
  1660                  ptr->nameUTF8 = (char*)gf_malloc((u32) ptr->size);
  1661                  if (!ptr->nameUTF8) return GF_OUT_OF_MEM;
  1662                  gf_bs_read_data(bs, ptr->nameUTF8, (u32) ptr->size);
  1663
  1664                  //patch for old QT files - we cannot rely on checking if str[0]==len(str+1) since we may have
  1665                  //cases where the first character of the string decimal value is indeed the same as the string length!!
  1666                  //we had this issue with encryption_import test
  1667                  //we therefore only check if last char is null, and if not so assume old QT style
  1668                  if (ptr->nameUTF8[ptr->size-1]) {
  1669                          memmove(ptr->nameUTF8, ptr->nameUTF8+1, sizeof(char) * (u32) (ptr->size-1) );
  1670                          ptr->nameUTF8[ptr->size-1] = 0;
  1671                          ptr->store_counted_string = GF_TRUE;
  1672                  }
  1673          }
  1674          return GF_OK;
  1675  }
